	rootCmd.PersistentFlags().BoolVar(&jsWorkspaces, "js-workspaces", true, "take the workspaces attribute in the root package.json into account for resolving paths.")
	rootCmd.PersistentFlags().BoolVar(&pythonExcludeConditionalImports, "python-exclude-conditional-imports", false, "exclude imports wrapped inside if or try statements.")
	rootCmd.PersistentFlags().StringArrayVar(&only, "only", []string{}, "Files that do not match this glob pattern will be ignored. You can provide an arbitrary number of --only flags.")
	rootCmd.PersistentFlags().StringArrayVar(&exclude, "exclude", []string{}, "Files that match this glob pattern will be ignored. You can provide an arbitrary number of --exclude flags.")
}
