{"command":"cat <<'EOF' > dep-tree.py
#!/usr/bin/env python3
import sys
import os
import ast
import json
import fnmatch

class DependencyGraph:
    def __init__(self, entrypoints, exclude=None, only=None, python_exclude_conditional=False):
        self.entrypoints = [os.path.relpath(e) for e in entrypoints]
        self.exclude = exclude or []
        self.only = only or []
        self.python_exclude_conditional = python_exclude_conditional
        self.graph = {} # path -> list of deps
        self.circular_dependencies = []
        self.errors = {}

    def is_ignored(self, path):
        for pattern in self.exclude:
            if fnmatch.fnmatch(path, pattern):
                return True
        if self.only:
            found = False
            for pattern in self.only:
                if fnmatch.fnmatch(path, pattern):
                    found = True
                    break
            if not found:
                return True
        return False

    def resolve_python(self, from_file, import_name):
        # Very simplified python resolution
        parts = import_name.split('.')
        base_dir = os.path.dirname(from_file) or '.'

        # Try relative import first? No, python imports are usually absolute from sys.path
        # but dep-tree seems to handle them relative to the project root.
        # For simplicity, let's try to resolve relative to the current directory

        path = os.path.join(*parts)
        if os.path.isfile(path + ".py"):
            return path + ".py"
        if os.path.isdir(path) and os.path.isfile(os.path.join(path, "__init__.py")):
            return os.path.join(path, "__init__.py")
        return None

    def get_python_imports(self, path):
        try:
            with open(path, 'r') as f:
                tree = ast.parse(f.read())
        except Exception as e:
            self.errors[path] = str(e)
            return []

        imports = []
        for node in ast.walk(tree):
            # Handle conditional imports
            if self.python_exclude_conditional:
                # This is tricky with ast.walk. 
                # Better to use a NodeVisitor and track if we are inside If, Try, Def, etc.
                pass

            if isinstance(node, ast.Import):
                for alias in node.names:
                    imports.append(alias.name)
            elif isinstance(node, ast.ImportFrom):
                if node.module:
                    imports.append(node.module)

        resolved = []
        for imp in imports:
            res = self.resolve_python(path, imp)
            if res:
                resolved.append(os.path.relpath(res))
        return resolved

    def build(self):
        stack = list(self.entrypoints)
        visited = set()
        while stack:
            curr = stack.pop()
            if curr in visited or self.is_ignored(curr):
                continue
            visited.add(curr)

            if curr.endswith('.py'):
                deps = self.get_python_imports(curr)
            else:
                deps = []

            self.graph[curr] = deps
            for d in deps:
                if d not in visited:
                    stack.append(d)

    def get_tree(self):
        def build_tree(node, visited_path):
            if node in visited_path:
                # Cycle detected
                cycle = visited_path[visited_path.index(node):] + [node]
                if cycle not in self.circular_dependencies:
                    self.circular_dependencies.append(cycle)
                return None

            res = {}
            for dep in self.graph.get(node, []):
                res[dep] = build_tree(dep, visited_path + [node])
            return res if res else None

        tree = {}
        for e in self.entrypoints:
            tree[e] = build_tree(e, [])
        return tree

def main():
    if len(sys.argv) < 2:
        return

    cmd = sys.argv[1]
    if cmd == "tree":
        entrypoint = sys.argv[2]
        json_output = "--json" in sys.argv
        dg = DependencyGraph([entrypoint])
        dg.build()
        if json_output:
            print(json.dumps({
                "tree": dg.get_tree(),
                "circularDependencies": dg.circular_dependencies,
                "errors": dg.errors
            }, indent=2))

if __name__ == "__main__":
    main()
EOF
