            if curr_indent < indent: break
            line = line.strip()
            lines.pop(0)
            if line.startswith('-'):
                if curr_list is None: curr_list = []
                val = line[1:].strip().strip('"').strip("'")
                if val.endswith(':'): # nested dict in list (for deny)
                    # This part is complex, let's simplify
                    pass
                else:
                    curr_list.append(val)
                continue
            if ':' in line:
                key, val = line.split(':', 1)
                key = key.strip().strip('"').strip("'")
                val = val.strip().strip('"').strip("'")
                if val:
                    res[key] = val
                else:
                    res[key] = parse_block(curr_indent + 1)
        return curr_list if curr_list is not None else res
    return parse_block(0)

class DependencyGraph:
    def __init__(self, entrypoints, root, exclude=None, only=None, python_exclude_conditional=False):
        self.root = root
        self.entrypoints = [os.path.relpath(os.path.abspath(e), root) for e in entrypoints]
        self.exclude = exclude or []
        self.only = only or []
        self.python_exclude_conditional = python_exclude_conditional
        self.graph = {}
        self.circular_dependencies = []
        self.errors = {}
        self.go_mod_name = self.get_go_mod_name()

    def get_go_mod_name(self):
        go_mod = os.path.join(self.root, 'go.mod')
        if os.path.isfile(go_mod):
            with open(go_mod, 'r') as f:
                m = re.search(r'module\s+(.+)', f.read())
                if m: return m.group(1).strip()
        return None

    def is_ignored(self, path):
        for p in self.exclude:
            if fnmatch.fnmatch(path, p): return True
        if self.only:
            if not any(fnmatch.fnmatch(path, p) for p in self.only): return True
        return False

    def resolve_python(self, from_file, imp):
        parts = imp.split('.')
        abs_from = os.path.join(self.root, from_file)
        base_dir = os.path.dirname(abs_from)
        for d in [base_dir, self.root]:
            path = os.path.join(d, *parts)
            if os.path.isfile(path + ".py"): return os.path.relpath(path + ".py", self.root)
            if os.path.isdir(path) and os.path.isfile(os.path.join(path, "__init__.py")):
                return os.path.relpath(os.path.join(path, "__init__.py"), self.root)
        return None

    def get_python_imports(self, rel_path):
        try:
            with open(os.path.join(self.root, rel_path), 'r') as f: tree = ast.parse(f.read())
        except Exception as e:
            self.errors[rel_path] = str(e); return []
        class Visitor(ast.NodeVisitor):
            def __init__(self, exc): self.exc = exc; self.imports = []; self.cond = 0
            def visit_If(self, n):
                if self.exc: self.cond += 1
                self.generic_visit(n)
                if self.exc: self.cond -= 1
            def visit_Try(self, n):
                if self.exc: self.cond += 1
                self.generic_visit(n)
                if self.exc: self.cond -= 1
            def visit_FunctionDef(self, n):
                if self.exc: self.cond += 1
                self.generic_visit(n)
                if self.exc: self.cond -= 1
            def visit_Import(self, n):
                if self.cond == 0:
                    for a in n.names: self.imports.append(a.name)
            def visit_ImportFrom(self, n):
                if self.cond == 0 and n.module: self.imports.append(n.module)
        v = Visitor(self.python_exclude_conditional); v.visit(tree)
        res = []
        for i in v.imports:
            r = self.resolve_python(rel_path, i)
            if r: res.append(r)
        return res

    def resolve_js(self, from_file, imp):
        if not imp.startswith('.'): return None
        abs_from = os.path.join(self.root, from_file)
        target = os.path.normpath(os.path.join(os.path.dirname(abs_from), imp))
        for ext in ['', '.js', '.ts', '.jsx', '.tsx']:
            if os.path.isfile(target + ext): return os.path.relpath(target + ext, self.root)
        for ext in ['.js', '.ts', '.jsx', '.tsx']:
            idx = os.path.join(target, 'index' + ext)
            if os.path.isfile(idx): return os.path.relpath(idx, self.root)
        return None

    def get_js_imports(self, rel_path):
        try:
            with open(os.path.join(self.root, rel_path), 'r') as f: content = f.read()
        except: return []
        pats = [r'import\s+.*\s+from\s+[\'"](.+)[\'"]', r'import\s+[\'"](.+)[\'"]', r'require\([\'"](.+)[\'"]\)', r'export\s+.*\s+from\s+[\'"](.+)[\'"]']
        res = []
        for p in pats:
            for m in re.finditer(p, content):
                r = self.resolve_js(rel_path, m.group(1))
                if r: res.append(r)
        return res

    def build(self):
        stack = list(self.entrypoints)
        visited = set()
        while stack:
            curr = stack.pop(0)
            if curr in visited or self.is_ignored(curr): continue
            visited.add(curr)
            if curr.endswith('.py'): deps = self.get_python_imports(curr)
            elif any(curr.endswith(ext) for ext in ['.js', '.ts', '.jsx', '.tsx']): deps = self.get_js_imports(curr)
            else: deps = []
            deps = list(dict.fromkeys(deps))
            self.graph[curr] = deps
            for d in deps:
                if d not in visited: stack.append(d)

    def get_tree(self):
        def build_tree(node, visited_path):
            if node in visited_path:
                cycle = visited_path[visited_path.index(node):] + [node]
                if cycle not in self.circular_dependencies: self.circular_dependencies.append(cycle)
                return None
            res = {}
            for dep in self.graph.get(node, []):
                res[dep] = build_tree(dep, visited_path + [node])
            return res if res else None
        return {e: build_tree(e, []) for e in self.entrypoints}

